final class EloquentOrderRepository implements OrderRepository
{
    public function findForOwner(string $uuid, User $owner): ?Order
    {
        return Order::query()
            ->whereKey($uuid)
            ->whereBelongsTo($owner)
            ->first();
    }
}

public function find_for_owner($public_id, $owner_id)
{
    $sql = 'SELECT o.public_id, o.total FROM orders o
            WHERE o.public_id = ? AND o.owner_id = ?';
    return $this->db->query($sql, [$public_id, $owner_id])->row();
}
